const protocolVersion = 1
export const name = 'flowix-dsh-bridge'
export const inject = ['settings', 'credentials', 'llm']
const capabilities = [
  'runtime-events', 'session-control', 'session-dispose', 'run-cancel', 'background-jobs', 'profile',
  'credentials-management', 'model-settings-management',
]
const modelNamespace = 'llm-pi-ai'

export default function plugin(ctx) {
  let transport, control
  const service = {
    protocolVersion,
    methods: [
      'flowix.bridge.capabilities', 'flowix.bridge.status',
      'flowix.bridge.session.ensure', 'flowix.bridge.session.prompt',
      'flowix.bridge.session.history', 'flowix.bridge.session.dispose',
      'flowix.bridge.run.cancel',
      'flowix.bridge.jobs.list',
      'flowix.bridge.credentials.describe', 'flowix.bridge.credentials.set',
      'flowix.bridge.credentials.unset',
      'flowix.bridge.models.describe', 'flowix.bridge.models.upsert',
      'flowix.bridge.models.remove', 'flowix.bridge.models.discover',
    ],
    attach(nextTransport, nextControl) {
      transport = nextTransport
      control = nextControl
      transport.notify('flowix.bridge.ready', { protocolVersion, capabilities })
      return () => { transport = undefined; control = undefined }
    },
    async handle(method, params = {}) {
      if (method === 'flowix.bridge.capabilities') return { protocolVersion, capabilities }
      if (method === 'flowix.bridge.credentials.describe') {
        return ctx.credentials.describe(credentialRef(params.reference))
      }
      if (method === 'flowix.bridge.credentials.set') {
        await ctx.credentials.set(credentialRef(params.reference), required(params.value, 'value'))
        return ctx.credentials.describe(credentialRef(params.reference))
      }
      if (method === 'flowix.bridge.credentials.unset') {
        const reference = credentialRef(params.reference)
        await ctx.credentials.unset(reference)
        return ctx.credentials.describe(reference)
      }
      if (method === 'flowix.bridge.models.describe') return describeModels(ctx)
      if (method === 'flowix.bridge.models.discover') {
        const request = record(params.request, 'request')
        return { models: await ctx.llm.discoverModels(modelNamespace, request) }
      }
      if (method === 'flowix.bridge.models.upsert') {
        const route = routeName(params.route)
        const profile = record(params.profile, 'profile')
        await ctx.settings.mutate(modelNamespace, [
          { op: 'set', path: ['providers', route], value: profile },
        ], optionalRevision(params.expectedRevision))
        return describeModels(ctx)
      }
      if (method === 'flowix.bridge.models.remove') {
        await ctx.settings.mutate(modelNamespace, [
          { op: 'unset', path: ['providers', routeName(params.route)] },
        ], optionalRevision(params.expectedRevision))
        return describeModels(ctx)
      }
      if (!control) throw new Error('Flowix DSH bridge is not attached to the SDK server')
      if (method === 'flowix.bridge.status') return { protocolVersion, ...await control.status() }
      const sessionId = required(params.sessionId, 'sessionId')
      if (method === 'flowix.bridge.session.ensure') return control.ensureSession(sessionId)
      if (method === 'flowix.bridge.session.prompt') {
        // The SDK extension control accepts the model-facing text itself. The
        // previous object payload became the `text` field of a DSH text block,
        // which later crashed consumers expecting `block.text` to be a string.
        required(params.displayText, 'displayText')
        required(params.clientMessageId, 'clientMessageId')
        return control.prompt(sessionId, required(params.modelText, 'modelText'))
      }
      if (method === 'flowix.bridge.session.history') {
        const persistence = ctx.get('sessionPersistence')
        if (!persistence?.inspect) throw new Error('DSH session persistence is unavailable')
        const snapshot = await persistence.inspect(sessionId)
        const events = Array.isArray(snapshot?.events) ? snapshot.events : []
        return { sessionId, events, snapshotSeq: events.reduce((max, event) => Math.max(max, Number(event?.seq) || 0), 0) }
      }
      if (method === 'flowix.bridge.session.dispose') return { disposed: await control.disposeSession(sessionId) }
      if (method === 'flowix.bridge.run.cancel') return { cancelled: await control.cancel(sessionId) }
      if (method === 'flowix.bridge.jobs.list') {
        // A runtime slot can be ready before the SDK server has published its
        // Agent (notably immediately after a host restart). Resolve through
        // the server's canonical session table first so owner-scoped jobs are
        // not accidentally filtered as if this were an agent-less caller.
        const ensured = await control.ensureSession(sessionId)
        const agent = ctx.agents.get(ensured.sessionId) ?? ctx.agents.get(sessionId)
        return { jobs: ctx.jobs.list(agent).map(job => ({
          id: job.id, kind: job.kind, label: job.label, status: job.status,
          ...(job.detail === undefined ? {} : { detail: job.detail }),
          startedAt: job.startedAt,
          ...(job.finishedAt === undefined ? {} : { finishedAt: job.finishedAt }),
        })) }
      }
      throw new Error(`unknown Flowix DSH bridge method: ${method}`)
    },
  }
  const disposers = [
    ctx.on('session/event', (session, event) => transport?.notify('flowix.bridge.event', { protocolVersion, kind: 'session.event', sessionId: String(session.id), event })),
    ctx.on('agent/status', ({ agent, status }) => transport?.notify('flowix.bridge.event', { protocolVersion, kind: 'agent.status', sessionId: String(agent.session.id), status })),
  ]
  ctx.provide('flowixDshBridge', service)
  // The SDK server reads this canonical service key when plugin scheduling
  // mounts the bridge before the server has subscribed to the ready event.
  // Publishing both the service and the event makes attachment independent
  // of Cordis sibling initialization order.
  ctx.provide('sdkJsonRpcExtension', service)
  ctx.emit('sdk/jsonrpc/extension/ready', service)
  return () => { for (const dispose of disposers) dispose(); transport = undefined; control = undefined }
}

// Cordis Loader unwraps an ESM default export before handing it to the
// registry, so named-export metadata is no longer present at that boundary.
// Mirror the injection declaration onto the actual default plugin function.
plugin.inject = inject

function describeModels(ctx) {
  const descriptor = ctx.settings.describe({ redactSecrets: true })
    .find(item => item.ns === modelNamespace)
  if (!descriptor) throw new Error('DSH llm-pi-ai settings namespace is unavailable')
  const user = isRecord(descriptor.user) ? descriptor.user : {}
  return {
    revision: descriptor.revision,
    providers: isRecord(user.providers) ? user.providers : {},
    applies: descriptor.applies,
  }
}

function credentialRef(value) {
  const reference = required(value, 'reference')
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(reference)) throw new Error('reference must be an environment-variable name')
  return reference
}
function routeName(value) {
  const route = required(value, 'route')
  if (route === '__proto__' || route === 'prototype' || route === 'constructor') throw new Error('invalid provider route')
  return route
}
function optionalRevision(value) {
  if (value === undefined) return undefined
  if (!Number.isSafeInteger(value) || value < 0) throw new Error('expectedRevision must be a non-negative integer')
  return value
}
function record(value, name) {
  if (!isRecord(value)) throw new Error(`${name} must be an object`)
  return value
}
function isRecord(value) { return value !== null && typeof value === 'object' && !Array.isArray(value) }
function required(value, name) {
  if (typeof value !== 'string' || value === '') throw new Error(`${name} must be a non-empty string`)
  return value
}
